from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

from Team_Phoenix_Library import phoenix_gyro_spin_turn_the_old_way

# Set up.
Left_attachment = Motor(Port.C, Direction.COUNTERCLOCKWISE)
Right__attachment = Motor(Port.E, Direction.CLOCKWISE)
Left_drive = Motor(Port.B, Direction.COUNTERCLOCKWISE)
Right_drive = Motor(Port.F, Direction.CLOCKWISE)
drive_base = DriveBase(Left_drive, Right_drive, 56, 87)

async def main1():
    await drive_base.straight(100)
    phoenix_gyro_spin_turn_the_old_way(100, -82, 40, -82, 'left', drive_base, Left_drive, Right_drive)
    drive_base.drive(100, 0)
    await wait(2000)
    drive_base.hold()
    await Right__attachment.run_angle(500, -120)
    await drive_base.straight(-50)
    await Right__attachment.run_angle(500, 120)
    await drive_base.straight(-150)
    phoenix_gyro_spin_turn_the_old_way(100, 35, 40, 35, 'left', drive_base, Left_drive, Right_drive)
    await drive_base.straight(-100)

async def main2():
    pass


async def main():
    await multitask(main1(), main2())

run_task(main())